<script setup>
import {computed,ref} from 'vue'
import {API_BASE} from '../api/client'
const props=defineProps({english:Boolean})
const step=ref(0),copyNotice=ref('')
const text=(zh,en)=>props.english?en:zh
const steps=computed(()=>[
 {title:text('安装插件','Install the extension'),body:text('Windows 用户下载并运行安装辅助工具，确认保存文件后点击“打开 Edge 管理页”。在 Edge 开启开发人员模式，点击“加载解压缩的扩展”，粘贴工具提供的路径并确认；其他电脑可使用 ZIP 手动安装。','On Windows, run the setup helper and approve saving the files. Open Edge management, enable Developer mode, choose Load unpacked and paste the folder path shown in the helper. The ZIP is available for manual installation on other computers.'),tip:text('只下载 ZIP 不算安装。插件需为 v0.3.0；返回 MKHP 确认“插件已安装并启用”。','Downloading the ZIP is not installation. Use v0.3.0 and confirm the installed message in MKHP.')},
 {title:text('找到插件按钮','Find the extension button'),body:text('插件在 Edge 浏览器右上角，不在 MHP 网页里。点击地址栏右侧的“扩展”（通常是拼图图标），在列表里找到“MHP 商品采集助手”，点击名称即可打开。也可固定到工具栏，方便下次使用。','The extension is in Edge’s toolbar, not inside the MHP page. Click Extensions (usually a puzzle icon) to the right of the address bar, then click MHP 商品采集助手. Pin it to the toolbar for easier access.'),tip:text('看不到插件？到 edge://extensions 确认安装且已启用，然后刷新 MHP。手机及桌面客户端内不能使用这个浏览器扩展。','Missing from the list? Confirm it is installed and enabled at edge://extensions, then refresh MHP. This extension does not run on phones or inside the desktop client.')},
 {title:text('准备两个网页标签','Open two browser tabs'),body:text('在同一个 Edge 窗口中，保留一个已登录并进入 MKHP 的 MHP 标签页；再打开你要采集的淘宝、天猫或拼多多商品详情页。自行完成登录、验证，选择规格，展开参数，等待商品信息加载。','In the same Edge browser, keep one signed-in MHP tab open on MKHP. In a second tab, open a supported Taobao, Tmall, or Pinduoduo product detail page. Sign in, complete verification, select the variant and expand its specifications.'),tip:text('商品链接在浏览器地址栏打开，无需粘贴到 MHP。不要同时打开多个 MHP 标签页。','Open the product URL in the browser address bar. Do not paste it into MHP. Keep only one MHP tab open.')},
 {title:text('在商品页点击采集','Collect from the product tab'),body:text('保持商品页为当前标签页，点击浏览器右上角的“MHP 商品采集助手”，再点击插件弹窗内的“读取当前商品页”。核对商品名称、候选价格和图片数量，然后点击“发送到已打开的 MKHP 预览”。','With the product tab active, open MHP 商品采集助手 from Edge’s toolbar and click 读取当前商品页. Review the candidate name, price and image count, then click 发送到已打开的 MKHP 预览.'),tip:text('这里的两个按钮位于浏览器插件弹窗内。采集不会自动保存图片，也不会调用 AI。','These two buttons are inside the extension popup. Collecting does not save images or call AI automatically.')},
 {title:text('核对后确认导入','Review and confirm the import'),body:text('插件会切回 MHP，并打开“核对浏览器采集内容”。检查或修正字段，勾选最多20张需要的图片，再点击“确认导入所选内容”。商品网址会自动带入，缺失尺寸、材质请在核实后手动补充。','The extension returns you to MHP and opens the review dialog. Check or edit fields, select up to 20 images, then confirm the import. The source URL is included automatically. Add missing dimensions or materials only after verifying them.'),tip:text('候选图可能包含推荐商品。显示缩略图会访问图片网址；确认导入后后端才下载所选图片。','Candidate images can include unrelated products. Showing thumbnails accesses image URLs; the backend downloads selected images only after you confirm.')},
 {title:text('查看结果并用于 PTMD','Use the archived material'),body:text('导入结果会出现在下方“采集历史”。点开记录，检查字段、来源和归档图片；如有下载失败，查看原因后决定是否重试。点击“前往此商品的 PTMD 示例文件夹”定位素材，或在单张图片下点击“用于 PTMD 示例图”直接选入参考。','Open the new entry in Collection history to inspect fields, sources and archived images. Review any download errors before retrying. Go to the PTMD reference library and select the archived source folder.'),tip:text('插件只负责采集与归档。文案和 AI 生图是后续独立操作；商品识别效果受原网页内容影响。','Collection and archiving are separate from copywriting and AI generation. Extraction depends on what the product page provides.')},
])
async function copyAddress(){try{await navigator.clipboard.writeText('edge://extensions');copyNotice.value=text('已复制，请粘贴到 Edge 地址栏并回车。','Copied. Paste into Edge’s address bar and press Enter.')}catch{copyNotice.value=text('请手动输入 edge://extensions 到地址栏。','Type edge://extensions in the address bar.')}}
function confirmDownload(event,helper=false){if(!window.confirm(text(helper?'允许下载 Windows 安装辅助工具吗？用途：确认后保存插件文件并协助打开 Edge 管理页，仍需手动加载扩展。':'允许下载插件 ZIP 吗？用途：手动解压并加载到 Edge。',helper?'Download the Windows helper? After your confirmation it saves the extension files and opens Edge management. Loading the extension remains manual.':'Download the extension ZIP for manual extraction and loading in Edge?')))event.preventDefault()}
</script>
<template>
 <div class="mkhp-quick-guide">
  <p class="guide-principle">{{text('无需在 MHP 粘贴商品链接。打开商品网页 → 浏览器插件采集 → 回到 MHP 核对导入。','No product URL form in MHP. Open the product page → collect with the browser extension → review in MHP.')}}</p>
  <nav class="guide-steps" :aria-label="text('教程步骤','Tutorial steps')"><button v-for="(item,index) in steps" :key="index" type="button" :aria-current="step===index?'step':undefined" @click="step=index"><b>{{index+1}}</b>{{item.title}}</button></nav>
  <div class="guide-step" aria-live="polite">
   <p class="guide-count">{{step+1}} / {{steps.length}}</p><h3>{{steps[step].title}}</h3><p>{{steps[step].body}}</p>
   <div v-if="step===0" class="guide-install"><a :href="`${API_BASE}/api/mkhp/collector/installer`" @click="confirmDownload($event,true)">{{text('下载 Windows 安装辅助工具','Download Windows setup helper')}}</a><a :href="`${API_BASE}/api/mkhp/collector/download`" @click="confirmDownload($event)">{{text('下载 Edge 插件 ZIP','Download Edge extension ZIP')}}</a><button type="button" @click="copyAddress">{{text('复制扩展管理地址','Copy extension settings address')}}</button><p v-if="copyNotice" role="status">{{copyNotice}}</p></div>
   <div v-if="step===1" class="browser-demo" role="img" :aria-label="text('示意：Edge 地址栏右侧，扩展菜单，MHP 商品采集助手','Diagram: Edge address bar → Extensions → MHP 商品采集助手')"><div class="browser-toolbar"><span>{{text('商品页 · 地址栏','Product page · Address bar')}}</span><strong>🧩 {{text('扩展','Extensions')}}</strong></div><div class="extension-menu">↓<br/><strong>MHP 商品采集助手</strong><small>{{text('点击这个名称打开插件','Click this name to open the extension')}}</small></div></div>
   <p class="guide-tip">{{steps[step].tip}}</p>
  </div>
  <div class="guide-controls"><button type="button" :disabled="step===0" @click="step--">{{text('上一步','Previous')}}</button><span>{{step+1}} / {{steps.length}}</span><button v-if="step<steps.length-1" type="button" @click="step++">{{text('下一步','Next')}}</button><button v-else type="button" @click="step=0">{{text('从头查看','Start again')}}</button></div>
 </div>
</template>
<style scoped>
.mkhp-quick-guide{line-height:1.75;overflow-wrap:anywhere}.guide-principle,.guide-tip{padding:12px 14px;background:var(--bg-sidebar,#f3f0e9);border-radius:8px}.guide-steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:14px 0}.guide-steps button{display:flex;gap:8px;align-items:center;text-align:left;font:inherit;font-size:12px;min-width:0;margin:0;padding:9px;background:var(--bg-glass,#fff);color:inherit;border:1px solid var(--border-dim,#ccc);border-radius:8px;cursor:pointer}.guide-steps b{flex-shrink:0}.guide-steps [aria-current=step]{border-color:var(--ink,#26251f);font-weight:700;background:var(--bg-sidebar,#f3f0e9)}.guide-step{min-height:210px}.guide-count{margin:0;font-size:12px;opacity:.7}.guide-step h3{margin:4px 0 12px}.guide-tip{border-left:3px solid var(--neon-blue,#bb602f);font-size:13px}.guide-controls{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:16px}.guide-controls button,.guide-install button{font:inherit;cursor:pointer;padding:8px 12px;border:1px solid var(--border-dim,#bbb);border-radius:8px;color:inherit;background:var(--bg-glass,#fff)}button:disabled{opacity:.45;cursor:default}.guide-install{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.guide-install p{flex-basis:100%}.browser-demo{border:1px solid var(--border-dim,#bbb);border-radius:10px;overflow:hidden;margin:15px 0;font-size:13px}.browser-toolbar{display:flex;gap:10px;align-items:center;padding:12px;background:var(--bg-sidebar,#eee)}.browser-toolbar span{flex:1;min-width:0}.browser-toolbar strong{border:2px solid var(--neon-blue,#bb602f);padding:5px 8px;border-radius:6px}.extension-menu{padding:10px 18px;text-align:right}.extension-menu strong,.extension-menu small{display:block}@media(max-width:500px){.guide-steps{grid-template-columns:repeat(2,minmax(0,1fr))}.guide-step{min-height:0}.browser-toolbar{font-size:11px}}
</style>
